1	// --- Price list: insurance values and base premiums ---
2	
3	/** The price list states one insurance value and one base premium per item kind. */
4	interface ListedPrice {
5	  insuranceValue: number;
6	  basePremium: number;
7	}
8	
9	const MAIN_ITEM_PRICE_LIST: Record<string, ListedPrice> = {
10	  sword: { insuranceValue: 1000, basePremium: 100 },
11	  amulet: { insuranceValue: 600, basePremium: 60 },
12	  staff: { insuranceValue: 800, basePremium: 80 },
13	  potion: { insuranceValue: 400, basePremium: 40 },
14	};
15	
16	const COMPONENT_PRICE: ListedPrice = { insuranceValue: 250, basePremium: 25 };
17	const COMPONENT_BLOCK_SIZE = 3;
18	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
19	
20	// --- Premium modifiers ---
21	const CURSE_SURCHARGE = 0.5;
22	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
23	const SURCHARGED_ENCHANTMENT_LEVEL = 5;
24	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
25	const LOYALTY_DISCOUNT = 0.2;
26	const LOYALTY_YEARS = 2;
27	const FIRST_INSURANCE_SURCHARGE = 0.1;
28	const PROCESSING_FEE = 5;
29	
30	// --- Claim processing ---
31	const DEDUCTIBLE_PER_DAMAGE = 100;
32	const PAYOUT_CAP_MULTIPLE = 2;
33	const HALF_REIMBURSED_ENCHANTMENT_LEVEL = 8;
34	const HALF_REIMBURSEMENT = 0.5;
35	const FULL_REIMBURSEMENT = 1;
36	
37	export interface Customer {
38	  yearsWithMHPCO: number;
39	}
40	
41	export interface Item {
42	  type: string;
43	  material?: string;
44	  enchantment?: number;
45	  cursed?: boolean;
46	}
47	
48	export interface QuoteStep {
49	  op: "quote";
50	  items: Item[];
51	}
52	
53	export interface Damage {
54	  itemType: string;
55	  amount: number;
56	}
57	
58	export interface Incident {
59	  cause: string;
60	  damages: Damage[];
61	}
62	
63	export interface ClaimStep {
64	  op: "claim";
65	  policy: number;
66	  incident: Incident;
67	}
68	
69	export type Step = QuoteStep | ClaimStep;
70	
71	export interface Scenario {
72	  customer: Customer;
73	  steps: Step[];
74	}
75	
76	export interface ScenarioResults {
77	  results: unknown[];
78	}
79	
80	const COMPONENT_TYPES = ["rune", "moonstone"];
81	
82	function isComponent(item: Item): boolean {
83	  return COMPONENT_TYPES.includes(item.type);
84	}
85	
86	/** Everything the price list prices individually, as opposed to by alike group. */
87	function isMainItem(item: Item): boolean {
88	  return item.type in MAIN_ITEM_PRICE_LIST;
89	}
90	
91	/** The MHPCO insures an item only if its type is named in the price list. */
92	function isInsurable(item: Item): boolean {
93	  return isMainItem(item) || isComponent(item);
94	}
95	
96	/**
97	 * Admission is the MHPCO's decision about what it is willing to cover at all,
98	 * taken before any pricing: an item the price list does not name cannot be
99	 * quoted, so the whole policy is refused.
100	 */
101	function admitToPolicy(items: Item[]): void {
102	  for (const item of items) {
103	    if (!isInsurable(item)) {
104	      throw new Error(`The MHPCO price list covers no item of type "${item.type}".`);
105	    }
106	  }
107	}
108	
109	/** Components are "alike" when they share a component type. */
110	function groupAlikeComponents(components: Item[]): Map<string, number> {
111	  const groupSizes = new Map<string, number>();
112	  for (const component of components) {
113	    const alikeness = component.type;
114	    groupSizes.set(alikeness, (groupSizes.get(alikeness) ?? 0) + 1);
115	  }
116	  return groupSizes;
117	}
118	
119	/** A building block of 3 alike components is offered at a special base premium. */
120	function alikeComponentGroupBasePremium(groupSize: number): number {
121	  return groupSize === COMPONENT_BLOCK_SIZE
122	    ? COMPONENT_BLOCK_BASE_PREMIUM
123	    : groupSize * COMPONENT_PRICE.basePremium;
124	}
125	
126	function mainItemsBasePremium(mainItems: Item[]): number {
127	  return mainItems.reduce((sum, item) => sum + MAIN_ITEM_PRICE_LIST[item.type].basePremium, 0);
128	}
129	
130	function componentsBasePremium(components: Item[]): number {
131	  let premium = 0;
132	  for (const groupSize of groupAlikeComponents(components).values()) {
133	    premium += alikeComponentGroupBasePremium(groupSize);
134	  }
135	  return premium;
136	}
137	
138	function policyBasePremium(items: Item[]): number {
139	  return (
140	    mainItemsBasePremium(items.filter(isMainItem)) +
141	    componentsBasePremium(items.filter(isComponent))
142	  );
143	}
144	
145	/**
146	 * An item-specific surcharge is a rate on the affected item's own base premium,
147	 * not on the policy's. Only main items carry a per-item base premium; a
148	 * component's belongs to its alike group, so the specification fixes no
149	 * surcharge for a cursed or highly enchanted component.
150	 *
151	 * Open question -- no example in the specification covers one, and no test
152	 * pins the outcome, so the behaviour here is undefined rather than decided:
153	 * the lookup misses and the premium becomes NaN. Settle it with a test before
154	 * relying on it; a quote is never reached with such an item today only because
155	 * no example produces one.
156	 */
157	function surchargeOnOwnBasePremium(item: Item, rate: number): number {
158	  return MAIN_ITEM_PRICE_LIST[item.type].basePremium * rate;
159	}
160	
161	function curseSurcharge(item: Item): number {
162	  return item.cursed === true ? surchargeOnOwnBasePremium(item, CURSE_SURCHARGE) : 0;
163	}
164	
165	/**
166	 * The premium surcharge for a highly enchanted item, from enchantment level 5
167	 * upwards. The claim side draws its own, higher enchantment line at level 8 for
168	 * half reimbursement -- two separate clauses, not one threshold used twice.
169	 */
170	function highEnchantmentSurcharge(item: Item): number {
171	  return (item.enchantment ?? 0) >= SURCHARGED_ENCHANTMENT_LEVEL
172	    ? surchargeOnOwnBasePremium(item, HIGH_ENCHANTMENT_SURCHARGE)
173	    : 0;
174	}
175	
176	/** Item-specific surcharges apply to the base premium of the affected item. */
177	function itemSurcharges(items: Item[]): number {
178	  return items.reduce(
179	    (sum, item) => sum + curseSurcharge(item) + highEnchantmentSurcharge(item),
180	    0,
181	  );
182	}
183	
184	/** A customer is long-standing from 2 years of business with MHPCO onwards. */
185	function loyaltyDiscount(basePremium: number, customer: Customer): number {
186	  return customer.yearsWithMHPCO >= LOYALTY_YEARS ? basePremium * LOYALTY_DISCOUNT : 0;
187	}
188	
189	/**
190	 * Every item in a quote is treated as a first insurance, regardless of customer
191	 * history, so the initial assessment surcharge carries no condition.
192	 */
193	function firstInsuranceSurcharge(basePremium: number): number {
194	  return basePremium * FIRST_INSURANCE_SURCHARGE;
195	}
196	
197	/** Customers receive a discount on each contract after their first. */
198	function followUpContractDiscount(basePremium: number, contractOrdinal: number): number {
199	  return contractOrdinal > 1 ? basePremium * FOLLOW_UP_CONTRACT_DISCOUNT : 0;
200	}
201	
202	/** Policy-wide modifiers apply to the policy base premium (the sum of all item base premiums). */
203	function policyWideModifiers(
204	  basePremium: number,
205	  customer: Customer,
206	  contractOrdinal: number,
207	): number {
208	  return (
209	    firstInsuranceSurcharge(basePremium) -
210	    loyaltyDiscount(basePremium, customer) -
211	    followUpContractDiscount(basePremium, contractOrdinal)
212	  );
213	}
214	
215	/** Rounding always favours the MHPCO; for a premium that means rounding up. */
216	function premiumRoundedInMHPCOsFavour(premium: number): number {
217	  return Math.ceil(premium);
218	}
219	
220	/**
221	 * The MHPCO prices a policy in one order: the policy base premium, then the
222	 * modifiers at their own scopes, then the processing fee at the very end.
223	 * Item-specific modifiers are charged against the base premium of the affected
224	 * item; policy-wide modifiers against the policy base premium. Only this final
225	 * amount is rounded -- intermediate amounts stay fractional.
226	 */
227	function quotePremium(items: Item[], customer: Customer, contractOrdinal: number): number {
228	  admitToPolicy(items);
229	  const basePremium = policyBasePremium(items);
230	  return premiumRoundedInMHPCOsFavour(
231	    basePremium +
232	      itemSurcharges(items) +
233	      policyWideModifiers(basePremium, customer, contractOrdinal) +
234	      PROCESSING_FEE,
235	  );
236	}
237	
238	/**
239	 * How many contracts the customer has taken out with MHPCO up to and including
240	 * the quote at this step. Every step is a quote today, so a step's position in
241	 * the scenario is its contract ordinal.
242	 */
243	function contractOrdinalOfStep(stepIndex: number): number {
244	  return stepIndex + 1;
245	}
246	
247	/** What the MHPCO would have to pay out if every insured item were destroyed. */
248	function insuranceSum(items: Item[]): number {
249	  return items.reduce(
250	    (sum, item) =>
251	      sum +
252	      (isComponent(item)
253	        ? COMPONENT_PRICE.insuranceValue
254	        : MAIN_ITEM_PRICE_LIST[item.type].insuranceValue),
255	    0,
256	  );
257	}
258	
259	/**
260	 * A policy created by a quote step: the MHPCO's remaining obligation under one
261	 * contract, measured two ways. `insuredItems` is the fixed coverage the contract
262	 * was written against; `remainingCap` is the money left under it, derived from
263	 * that coverage at opening and drawn down by each claim. They belong together
264	 * because the cap is a function of the coverage, not an unrelated counter.
265	 */
266	interface Policy {
267	  insuredItems: Item[];
268	  remainingCap: number;
269	}
270	
271	function openPolicy(items: Item[]): Policy {
272	  return { insuredItems: items, remainingCap: insuranceSum(items) * PAYOUT_CAP_MULTIPLE };
273	}
274	
275	/**
276	 * Damage to an item of enchantment level 8 or more is reimbursed at half the
277	 * damage amount. This is the claim side's own enchantment line, above the
278	 * level 5 that earns a premium surcharge.
279	 */
280	function isHalfReimbursed(item: Item): boolean {
281	  return (item.enchantment ?? 0) >= HALF_REIMBURSED_ENCHANTMENT_LEVEL;
282	}
283	
284	/**
285	 * The fraction of a damage amount the reimbursement clauses allow for this
286	 * item, before the deductible is taken. One clause is in force today; the
287	 * specification describes others (dragon material) and a precedence between
288	 * them, so this is the one place a clause is chosen.
289	 */
290	function reimbursementRateFor(damagedItem: Item): number {
291	  return isHalfReimbursed(damagedItem) ? HALF_REIMBURSEMENT : FULL_REIMBURSEMENT;
292	}
293	
294	/** The share of a damage the MHPCO reimburses before the deductible is taken. */
295	function reimbursableDamage(damage: Damage, damagedItem: Item): number {
296	  return damage.amount * reimbursementRateFor(damagedItem);
297	}
298	
299	/**
300	 * The deductible is the claimant's own share of each damage event: the MHPCO
301	 * reimburses what the damage exceeds it by.
302	 *
303	 * Adopted reading -- the specification says only that "a deductible of 100 G
304	 * applies per damage event", and fixes no outcome for a damage smaller than
305	 * the deductible. A deductible reduces a reimbursement; it does not bill the
306	 * claimant, so a damage at or below it is reimbursed at nothing rather than
307	 * at a negative amount. Settle it against the MHPCO before relying on it.
308	 */
309	function reimbursementAfterDeductible(damage: Damage, damagedItem: Item): number {
310	  const excessOverDeductible = reimbursableDamage(damage, damagedItem) - DEDUCTIBLE_PER_DAMAGE;
311	  return Math.max(excessOverDeductible, 0);
312	}
313	
314	interface ClaimResult {
315	  payout: number;
316	  remainingCap: number;
317	}
318	
319	/**
320	 * The insured item a damage entry refers to.
321	 *
322	 * The specification does reject a claim that names an item the policy does not
323	 * cover, so this throw is the start of a real MHPCO decision rather than a
324	 * type-system formality -- but no active test pins it yet, and the rejection it
325	 * will eventually serve is broader than what happens here (it also covers more
326	 * damage entries of a type than the policy insures). Treat the current throw as
327	 * unpinned: the behaviour stands, the clause is not yet designed.
328	 */
329	function damagedItemIn(policy: Policy, damage: Damage): Item {
330	  const item = policy.insuredItems.find((insured) => insured.type === damage.itemType);
331	  if (item === undefined) {
332	    throw new Error(`The policy covers no item of type "${damage.itemType}".`);
333	  }
334	  return item;
335	}
336	
337	/**
338	 * Settling an incident both pays the claimant and uses up part of the cap the
339	 * policy carries for the rest of its life, so the settled policy is the second
340	 * half of the outcome rather than a side effect: a claim leaves the policy in a
341	 * new state, and later claims against it see that state.
342	 */
343	function settleClaim(policy: Policy, incident: Incident): { result: ClaimResult; policy: Policy } {
344	  const payout = incident.damages.reduce(
345	    (sum, damage) => sum + reimbursementAfterDeductible(damage, damagedItemIn(policy, damage)),
346	    0,
347	  );
348	  const settled: Policy = { ...policy, remainingCap: policy.remainingCap - payout };
349	  return { result: { payout, remainingCap: settled.remainingCap }, policy: settled };
350	}
351	
352	export function runScenario(scenario: Scenario): ScenarioResults {
353	  /** Policies opened so far, addressed the way the input does: by the index of the quote step that opened each. */
354	  const policies = new Map<number, Policy>();
355	
356	  /**
357	   * A claim naming a step that opened no policy is outside the specification --
358	   * no example and no test describes it -- so this guard exists only to keep the
359	   * lookup total for the type system.
360	   */
361	  const policyOpenedBy = (quoteStepIndex: number): Policy => {
362	    const policy = policies.get(quoteStepIndex);
363	    if (policy === undefined) {
364	      throw new Error(`No policy was created by step ${String(quoteStepIndex)}.`);
365	    }
366	    return policy;
367	  };
368	
369	  const results = scenario.steps.map((step, stepIndex) => {
370	    if (step.op === "claim") {
371	      const { result, policy } = settleClaim(policyOpenedBy(step.policy), step.incident);
372	      policies.set(step.policy, policy);
373	      return result;
374	    }
375	    policies.set(stepIndex, openPolicy(step.items));
376	    return {
377	      premium: quotePremium(step.items, scenario.customer, contractOrdinalOfStep(stepIndex)),
378	    };
379	  });
380	  return { results };
381	}
