1	import { describe, expect, it } from "vitest";
2	import { type Incident, type Item, runScenario } from "./claim-office.js";
3	
4	// Observable contract readings adopted where the specification leaves them open:
5	// - Rejections ("exits with a non-zero status code", "writes an error description
6	//   to stderr") are modelled as the scenario runner throwing an Error; the CLI
7	//   adapter translates a thrown Error into exit code 1 plus a stderr description.
8	//   The specification establishes no error type or message, so tests require only
9	//   that an Error is thrown / that the CLI exits non-zero with non-empty stderr.
10	// - "Alike" components means the same component type (2 runes + 1 moonstone is no
11	//   block), as fixed by the specification's example.
12	
13	/**
14	 * The premium the claim office quotes for a first contract covering these items.
15	 * Customer tenure is a spec input, so it stays explicit; it defaults to the
16	 * newcomer (0 years) that every example below describes.
17	 */
18	function premiumQuotedFor(items: Item[], yearsWithMHPCO = 0): number {
19	  const { results } = runScenario({
20	    customer: { yearsWithMHPCO },
21	    steps: [{ op: "quote", items }],
22	  });
23	  return (results[0] as { premium: number }).premium;
24	}
25	
26	/**
27	 * The claim result the office settles when this incident is reported against a
28	 * freshly quoted policy covering these items -- the quote-then-claim envelope
29	 * every claim example in the specification describes.
30	 */
31	function claimSettledOn(
32	  insuredItems: Item[],
33	  incident: Incident,
34	): { payout: number; remainingCap: number } {
35	  const { results } = runScenario({
36	    customer: { yearsWithMHPCO: 0 },
37	    steps: [
38	      { op: "quote", items: insuredItems },
39	      { op: "claim", policy: 0, incident },
40	    ],
41	  });
42	  return results[1] as { payout: number; remainingCap: number };
43	}
44	
45	describe("MHPCO Claim Office", () => {
46	  // --- Quote: simplest case ---
47	  it("empty item list -> premium 5 G (processing fee only)", () => {
48	    expect(premiumQuotedFor([])).toBe(5);
49	  });
50	
51	  // --- Quote: main item base premiums (price-list catalogue, one test per entry) ---
52	  it("single sword, no modifiers, 0 years, 1st contract -> premium 115 G (100 base + 10 first insurance + 5 fee)", () => {
53	    expect(premiumQuotedFor([{ type: "sword", material: "steel", enchantment: 1, cursed: false }])).toBe(115);
54	  });
55	  it("single amulet, no modifiers, 0 years, 1st contract -> premium 71 G (60 base + 6 first insurance + 5 fee)", () => {
56	    expect(premiumQuotedFor([{ type: "amulet", material: "silver", enchantment: 1, cursed: false }])).toBe(71);
57	  });
58	  it("single staff, no modifiers, 0 years, 1st contract -> premium 93 G (80 base + 8 first insurance + 5 fee)", () => {
59	    expect(premiumQuotedFor([{ type: "staff", material: "oak", enchantment: 1, cursed: false }])).toBe(93);
60	  });
61	  it("single potion, no modifiers, 0 years, 1st contract -> premium 49 G (40 base + 4 first insurance + 5 fee)", () => {
62	    expect(premiumQuotedFor([{ type: "potion", material: "glass", enchantment: 1, cursed: false }])).toBe(49);
63	  });
64	
65	  // --- Quote: component base premiums and the building block ---
66	  it("1 rune -> base premium 25 G; premium 33 G (25 base + 2.5 first insurance + 5 fee, rounded up)", () => {
67	    expect(premiumQuotedFor([{ type: "rune" }])).toBe(33);
68	  });
69	  it("moonstones are components too: 2 moonstones -> base premium 50 G; premium 60 G", () => {
70	    expect(premiumQuotedFor([{ type: "moonstone" }, { type: "moonstone" }])).toBe(60);
71	  });
72	  it("2 runes -> base premium 50 G (no block); premium 60 G (50 base + 5 first insurance + 5 fee)", () => {
73	    expect(premiumQuotedFor([{ type: "rune" }, { type: "rune" }])).toBe(60);
74	  });
75	  it("3 runes -> base premium 60 G (block applies); premium 71 G (60 base + 6 first insurance + 5 fee)", () => {
76	    expect(premiumQuotedFor([{ type: "rune" }, { type: "rune" }, { type: "rune" }])).toBe(71);
77	  });
78	  it("4 runes -> base premium 100 G (no block -- block requires exactly 3); premium 115 G", () => {
79	    expect(premiumQuotedFor(Array.from({ length: 4 }, () => ({ type: "rune" })))).toBe(115);
80	  });
81	  it("7 runes -> base premium 175 G (no block -- block requires exactly 3); premium 198 G", () => {
82	    expect(premiumQuotedFor(Array.from({ length: 7 }, () => ({ type: "rune" })))).toBe(198);
83	  });
84	  it("2 runes + 1 moonstone -> base premium 75 G (no block: different types); premium 88 G", () => {
85	    expect(premiumQuotedFor([{ type: "rune" }, { type: "rune" }, { type: "moonstone" }])).toBe(88);
86	  });
87	  it("3 runes + 3 moonstones -> base premium 120 G (two separate blocks); premium 137 G", () => {
88	    expect(
89	      premiumQuotedFor([
90	        { type: "rune" }, { type: "rune" }, { type: "rune" },
91	        { type: "moonstone" }, { type: "moonstone" }, { type: "moonstone" },
92	      ]),
93	    ).toBe(137);
94	  });
95	
96	  // --- Quote: item-specific modifiers ---
97	  it("cursed sword adds a 50 % surcharge on that item's base premium -> 50 G added; premium 165 G", () => {
98	    expect(premiumQuotedFor([{ type: "sword", material: "steel", enchantment: 3, cursed: true }])).toBe(165);
99	  });
100	  it("sword with enchantment 5 adds a 30 % high-enchantment surcharge -> 30 G added (threshold is inclusive); premium 145 G", () => {
101	    expect(premiumQuotedFor([{ type: "sword", material: "steel", enchantment: 5, cursed: false }])).toBe(145);
102	  });
103	  it("sword with enchantment 4 adds no high-enchantment surcharge; premium 115 G", () => {
104	    expect(premiumQuotedFor([{ type: "sword", material: "steel", enchantment: 4, cursed: false }])).toBe(115);
105	  });
106	  it("cursed sword with enchantment 5 adds both surcharges -> 50 G + 30 G added; premium 195 G", () => {
107	    expect(premiumQuotedFor([{ type: "sword", material: "steel", enchantment: 5, cursed: true }])).toBe(195);
108	  });
109	
110	  // --- Quote: policy-wide modifiers ---
111	  it("customer with exactly 2 years with MHPCO receives the 20 % loyalty discount; sword premium 95 G", () => {
112	    expect(
113	      premiumQuotedFor([{ type: "sword", material: "steel", enchantment: 1, cursed: false }], 2),
114	    ).toBe(95);
115	  });
116	  it("customer with 1 year with MHPCO receives no loyalty discount; sword premium 115 G", () => {
117	    expect(
118	      premiumQuotedFor([{ type: "sword", material: "steel", enchantment: 1, cursed: false }], 1),
119	    ).toBe(115);
120	  });
121	  it("every quote carries the 10 % first-insurance surcharge on the policy base premium; staff premium 93 G", () => {
122	    // Shares the single-staff witness with the price-list test above: the staff
123	    // scenario is the specification's plainest quote, so it is the clearest
124	    // evidence both for the 80 G price-list entry and for the surcharge applying
125	    // to a newcomer's quote with no other modifier in play. Two spec statements,
126	    // one witness -- neither test can go without losing a statement.
127	    expect(premiumQuotedFor([{ type: "staff", material: "oak", enchantment: 1, cursed: false }])).toBe(93);
128	  });
129	  it("the second quote in a scenario receives the 15 % follow-up-contract discount; sword premiums 115 G then 100 G", () => {
130	    const sword = { type: "sword", material: "steel", enchantment: 1, cursed: false };
131	    expect(
132	      runScenario({
133	        customer: { yearsWithMHPCO: 0 },
134	        steps: [
135	          { op: "quote", items: [sword] },
136	          { op: "quote", items: [sword] },
137	        ],
138	      }),
139	    ).toEqual({ results: [{ premium: 115 }, { premium: 100 }] });
140	  });
141	  it("the first quote in a scenario receives no follow-up-contract discount; sword premium 115 G", () => {
142	    expect(premiumQuotedFor([{ type: "sword", material: "steel", enchantment: 1, cursed: false }])).toBe(115);
143	  });
144	  // --- Quote: the processing fee's place in the calculation order ---
145	  it("the 5 G processing fee is added at the very end, after all modifiers -- it is not discounted by loyalty", () => {
146	    // 2-year customer, sword: 100 base - 20 loyalty + 10 first insurance = 90, then + 5 fee = 95.
147	    // Had the fee been added before the policy-wide modifiers, the result would be 94.5 -> 95 too,
148	    // so a cursed staff discriminates: 80 base + 40 curse - 16 loyalty + 8 first insurance = 112, + 5 = 117.
149	    expect(
150	      premiumQuotedFor([{ type: "staff", material: "oak", enchantment: 1, cursed: true }], 2),
151	    ).toBe(117);
152	  });
153	
154	  // --- Quote: modifier scope on multi-item policies ---
155	  it("cursed sword (100 G) + plain amulet (60 G) -> policy base 160 G, curse adds 50 G (of the sword only) -> 210 G before policy-wide modifiers and fee; premium 231 G", () => {
156	    expect(
157	      premiumQuotedFor([
158	        { type: "sword", material: "steel", enchantment: 1, cursed: true },
159	        { type: "amulet", material: "silver", enchantment: 1, cursed: false },
160	      ]),
161	    ).toBe(231);
162	  });
