 * Only the high-enchantment clause is in force today. The specification
 * describes a dragon-material clause as well, and gives the precedence
 * between them -- the 50 % rule wins where both apply -- but no active test
 * pins that clause, so it is not expressed here yet.
 */
function reimbursementRateFor(damagedItem: Item): number {
  return isHalfReimbursed(damagedItem) ? HALF_REIMBURSEMENT : STANDARD_REIMBURSEMENT;
}

